// MarketplaceServiceHandler is an implementation of the
// talgent.marketplace.public.v1.MarketplaceService service.
type MarketplaceServiceHandler interface {
	// BeginProviderAuthorization manages the authenticated user's personal connection.
	BeginProviderAuthorization(context.Context, *connect.Request[v1.BeginProviderAuthorizationRequest]) (*connect.Response[v1.BeginProviderAuthorizationResponse], error)
	// CompleteProviderAuthorization manages the authenticated user's personal connection.
	CompleteProviderAuthorization(context.Context, *connect.Request[v1.CompleteProviderAuthorizationRequest]) (*connect.Response[v1.CompleteProviderAuthorizationResponse], error)
	// GetProviderConnectionState manages the authenticated user's personal connection.
	GetProviderConnectionState(context.Context, *connect.Request[v1.GetProviderConnectionStateRequest]) (*connect.Response[v1.GetProviderConnectionStateResponse], error)
	// ListAccessibleRepositories lists repositories last observed as reachable under the user's authorization.
	ListAccessibleRepositories(context.Context, *connect.Request[v1.ListAccessibleRepositoriesRequest]) (*connect.Response[v1.ListAccessibleRepositoriesResponse], error)
	// GetProviderAccess describes the accounts, repositories and permissions the authorization last reached.
	GetProviderAccess(context.Context, *connect.Request[v1.GetProviderAccessRequest]) (*connect.Response[v1.GetProviderAccessResponse], error)
	// RefreshProviderAccess observes the authorization's reach now and returns it.
	RefreshProviderAccess(context.Context, *connect.Request[v1.RefreshProviderAccessRequest]) (*connect.Response[v1.RefreshProviderAccessResponse], error)
	// List configured personal authorization references, including inactive ones.
	ListPersonalAuthorizations(context.Context, *connect.Request[v1.ListPersonalAuthorizationsRequest]) (*connect.Response[v1.ListPersonalAuthorizationsResponse], error)
	// Ask the Provider to revoke the authenticated user's personal authorization.
	CancelPersonalAuthorization(context.Context, *connect.Request[v1.CancelPersonalAuthorizationRequest]) (*connect.Response[v1.CancelPersonalAuthorizationResponse], error)
	// Browse synchronized plugin releases.
	ListPlugins(context.Context, *connect.Request[v1.ListPluginsRequest]) (*connect.Response[v1.ListPluginsResponse], error)
	// Read the currently selected immutable release for a slug.
	GetPlugin(context.Context, *connect.Request[v1.GetPluginRequest]) (*connect.Response[v1.GetPluginResponse], error)
	// List the authenticated user's personal installations.
	ListInstalledPlugins(context.Context, *connect.Request[v1.ListInstalledPluginsRequest]) (*connect.Response[v1.ListInstalledPluginsResponse], error)
	// Read one personal installation including manual configuration.
	GetInstalledPlugin(context.Context, *connect.Request[v1.GetInstalledPluginRequest]) (*connect.Response[v1.GetInstalledPluginResponse], error)
	// Install a personal plugin; repeating preserves existing choices.
	InstallPlugin(context.Context, *connect.Request[v1.InstallPluginRequest]) (*connect.Response[v1.InstallPluginResponse], error)
	// Include a personal installation in future default selections.
	EnablePlugin(context.Context, *connect.Request[v1.EnablePluginRequest]) (*connect.Response[v1.EnablePluginResponse], error)
	// Exclude a personal installation while retaining its configuration.
	DisablePlugin(context.Context, *connect.Request[v1.DisablePluginRequest]) (*connect.Response[v1.DisablePluginResponse], error)
	// Set typed manual values after validation.
	SetPluginConfiguration(context.Context, *connect.Request[v1.SetPluginConfigurationRequest]) (*connect.Response[v1.SetPluginConfigurationResponse], error)
	// Delete manual choices after validation.
	DeletePluginConfiguration(context.Context, *connect.Request[v1.DeletePluginConfigurationRequest]) (*connect.Response[v1.DeletePluginConfigurationResponse], error)
	// Remove a personal installation and its manual configuration.
	UninstallPlugin(context.Context, *connect.Request[v1.UninstallPluginRequest]) (*connect.Response[v1.UninstallPluginResponse], error)
	// Browse the platform Connector catalog with the user's personal status.
	ListConnectors(context.Context, *connect.Request[v1.ListConnectorsRequest]) (*connect.Response[v1.ListConnectorsResponse], error)
	// Read one catalog Connector with the Plugins that use it.
	GetConnector(context.Context, *connect.Request[v1.GetConnectorRequest]) (*connect.Response[v1.GetConnectorResponse], error)
	// List required Connectors and the user's personal installations.
	ListInstalledConnectors(context.Context, *connect.Request[v1.ListInstalledConnectorsRequest]) (*connect.Response[v1.ListInstalledConnectorsResponse], error)
	// Install a catalog Connector; Provider authorization is not required.
	InstallConnector(context.Context, *connect.Request[v1.InstallConnectorRequest]) (*connect.Response[v1.InstallConnectorResponse], error)
	// Include an installed Connector in future default selections.
	EnableConnector(context.Context, *connect.Request[v1.EnableConnectorRequest]) (*connect.Response[v1.EnableConnectorResponse], error)
	// Exclude an installed Connector while keeping the installation.
	DisableConnector(context.Context, *connect.Request[v1.DisableConnectorRequest]) (*connect.Response[v1.DisableConnectorResponse], error)
	// Remove a personal Connector installation; authorization is unaffected.
	UninstallConnector(context.Context, *connect.Request[v1.UninstallConnectorRequest]) (*connect.Response[v1.UninstallConnectorResponse], error)
}

